using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using UnityEngine.Rendering.Universal;using UnityEngine.InputSystem;using Newtonsoft.Json;
public static class BMAudit {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>R+"/Docs/Review/2026-11-09_B2_FullFloor/";static Vector3 origin=new Vector3(19,-34,-1);
 static Scene Check(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 edit required");Directory.CreateDirectory(O);return s;}
 public static object Audit(){var s=Check();var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var mf=all.SelectMany(t=>t.GetComponents<MeshFilter>()).ToArray();var rs=all.SelectMany(t=>t.GetComponents<Renderer>()).ToArray();var meshes=mf.Where(m=>m.sharedMesh).Select(m=>m.sharedMesh).Distinct().ToArray();var bad=new List<object>();long tri=0;foreach(var m in meshes){for(int i=0;i<m.subMeshCount;i++)tri+=(long)m.GetIndexCount(i)/3;if(!m.isReadable)continue;var v=m.vertices;var ix=m.triangles;int n=0;for(int i=0;i<ix.Length;i+=3)if(Vector3.Cross(v[ix[i+1]]-v[ix[i]],v[ix[i+2]]-v[ix[i]]).sqrMagnitude<1e-16f)n++;if(n>0)bad.Add(new{m.name,degenerate=n});}
 var result=new{scene=s.path,saved=!s.isDirty,objects=all.Length,renderers=rs.Length,uniqueTriangles=tri,missingMeshes=mf.Count(f=>!f.sharedMesh),missingMaterials=rs.Sum(r=>r.sharedMaterials.Count(m=>!m)),missingScripts=all.Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)),nonASCII=all.Count(t=>t.name.Any(c=>c>127)),colliders=all.Sum(t=>t.GetComponents<Collider>().Length),lights=all.Sum(t=>t.GetComponents<Light>().Length),lodGroups=all.Sum(t=>t.GetComponents<LODGroup>().Length),probes=all.Sum(t=>t.GetComponents<ReflectionProbe>().Length),meshIssues=bad,mouse=Mouse.current?.enabled,keyboard=Keyboard.current?.enabled};File.WriteAllText(O+"audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
